#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;
class Solution {
public:
    int findMaxLength(vector<int>& nums) {
        unordered_map<int, int> seen;
        seen[0] = -1;
        int balance = 0, maxLen = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            balance += (nums[i] % 2 != 0) ? 1 : -1;
            if (seen.count(balance)) maxLen = max(maxLen, i - seen[balance]);
            else seen[balance] = i;
        }
        return maxLen;
    }
};
